6	import { BasePromptElementProps, PromptElement, PromptElementProps, PromptSizing } from '@vscode/prompt-tsx';
7	import type { LanguageModelToolInformation } from 'vscode';
8	import { modelSupportsToolSearch } from '../../../../platform/endpoint/common/chatModelCapabilities';
9	import { CUSTOM_TOOL_SEARCH_NAME } from '../../../../platform/networking/common/anthropic';
10	import { IToolDeferralService } from '../../../../platform/networking/common/toolDeferralService';
11	import { IChatEndpoint } from '../../../../platform/networking/common/networking';
